import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple
import math
import random

# --- Resources and Components ---
RESOURCES = {
    "wood": {"cost": 1},
    "stone": {"cost": 2},
    "metal": {"cost": 3},
}

COMPONENTS = {
    "foundation": {"resources": {"stone": 2, "wood": 1}, "craft_time": 2},
    "wall_segment": {"resources": {"wood": 2, "metal": 1}, "craft_time": 3},
    "roof_panel": {"resources": {"wood": 3}, "craft_time": 1},
    "door_frame": {"resources": {"wood": 1, "metal": 2}, "craft_time": 2}, # New component for dynamic task
}

# --- Building Structure ---
BUILDING_PLAN = {
    "house_phase1": [
        ("foundation_1", []), 
        ("foundation_2", []),
        ("wall_segment_1", ["foundation_1"]), 
        ("wall_segment_2", ["foundation_2"]),
    ],
    "house_phase2": [ # New phase with new dependencies
        ("roof_panel_1", ["wall_segment_1", "wall_segment_2"]), 
        ("door_frame_1", ["wall_segment_1"]), # Door needs a wall
    ]
}

class Resource:
    def __init__(self, resource_id: str, amount: int):
        self.id = resource_id
        self.amount = amount

class Component:
    def __init__(self, component_id: str, blueprint: Dict[str, Any]):
        self.id = component_id
        self.resources_needed = blueprint["resources"].copy()
        self.craft_time = blueprint["craft_time"]
        self.current_craft_time = 0
        self.ready_for_assembly = False

    def add_craft_time(self, amount: int):
        if not self.ready_for_assembly:
            self.current_craft_time += amount
            if self.current_craft_time >= self.craft_time:
                self.ready_for_assembly = True

class BuildingComponent:
    def __init__(self, component_id: str, dependencies: List[str]):
        self.id = component_id
        self.dependencies = dependencies
        self.crafted_ready = False 
        self.assembled = False

    def check_crafted_ready(self, world_components: Dict[str, Component]):
        base_comp_id = '_'.join(self.id.split('_')[:-1])
        if base_comp_id in world_components and world_components[base_comp_id].ready_for_assembly:
            self.crafted_ready = True

    def check_dependencies(self, building_status: Dict[str, 'BuildingComponent']) -> bool:
        return all(building_status[dep].assembled for dep in self.dependencies)

    def assemble(self):
        if self.crafted_ready and not self.assembled:
            self.assembled = True

class ConstructionAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], num_agents: int, learning_rate: float = 0.1, epsilon_start: float = 0.08, epsilon_end: float = 0.02, mutation_rate: float = 0.05, preferred_action: str = None):
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.num_agents = num_agents
        self.total_reward = 0
        self.learning_rate = learning_rate
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.mutation_rate = mutation_rate
        self.preferred_action = preferred_action

        self.action_strategy = defaultdict(lambda: {'success': 1, 'attempts': 2, 'value_est': 0.5})
        if self.preferred_action:
            self.action_strategy[self.preferred_action]['value_est'] = 0.9

        self.reputations = {aid: 0.5 for aid in all_agent_ids if aid != agent_id}

        self.action_history_window = 20
        self.recent_actions = defaultdict(lambda: [])
        self.specialization_index = 0.0
        self.most_specialized_action = "None"

        self.current_resources = {} 
        for res_id in RESOURCES.keys():
            self.current_resources[res_id] = 0

        print(f"Construction Agent {self.agent_id} initialized (LR: {self.learning_rate:.2f}, M: {self.mutation_rate:.2f}, Pref: {self.preferred_action}).")

    def _get_epsilon(self, current_round: int, total_rounds: int) -> float:
        decay_rate = (self.epsilon_start - self.epsilon_end) / total_rounds
        return max(self.epsilon_end, self.epsilon_start - decay_rate * current_round)

    def choose_action(self, available_tasks: List[str], current_round: int, total_rounds: int, env_world_components: Dict[str, Component], env_building_status: Dict[str, BuildingComponent]) -> Tuple[str, str]:
        current_epsilon = self._get_epsilon(current_round, total_rounds)

        action_type = "gather" 
        target_id = None

        if np.random.rand() < current_epsilon:
            action_type = np.random.choice(["gather", "craft", "assemble"])
            if action_type == "gather":
                target_id = np.random.choice(list(RESOURCES.keys()))
            elif action_type == "craft":
                target_id = np.random.choice(list(COMPONENTS.keys()))
            elif action_type == "assemble":
                unassembled_components = [bc_id for bc_id, bc in env_building_status.items() if not bc.assembled]
                target_id = np.random.choice(unassembled_components) if unassembled_components else None
        else:
            action_values = {}

            for a_type in ["gather", "craft", "assemble"]:
                possible_targets = []
                if a_type == "gather":
                    possible_targets = list(RESOURCES.keys())
                elif a_type == "craft":
                    possible_targets = list(COMPONENTS.keys())
                elif a_type == "assemble":
                    possible_targets = [bc_id for bc_id, bc in env_building_status.items() if not bc.assembled]

                for t_id in possible_targets:
                    action_key = f"{a_type}_{t_id}"
                    value = self.action_strategy[action_key]['value_est']
                    action_values[action_key] = value

            if action_values:
                chosen_action_key = max(action_values, key=action_values.get)
                parts = chosen_action_key.split('_')
                action_type = parts[0]
                target_id = '_'.join(parts[1:])
            else: 
                action_type = "gather"
                target_id = np.random.choice(list(RESOURCES.keys()))

        return action_type, target_id

    def update_learning(self, chosen_action: Tuple[str, str], collective_round_reward: float, world_components: Dict[str, Component], current_max_possible_collective_reward: float, current_round: int):
        self.total_reward += collective_round_reward

        action_key = f"{chosen_action[0]}_{chosen_action[1]}"

        reward_signal = collective_round_reward / current_max_possible_collective_reward if current_max_possible_collective_reward > 0 else 0.5

        self.action_strategy[action_key]['attempts'] += 1
        self.action_strategy[action_key]['value_est'] = np.clip(
            (1 - self.learning_rate) * self.action_strategy[action_key]['value_est'] + \
            self.learning_rate * reward_signal, 0, 1)

    def update_reputation_from_round_outcome(self, collective_round_reward: float, max_possible_collective_reward_this_round: float):
        if max_possible_collective_reward_this_round > 0:
            performance_score = collective_round_reward / max_possible_collective_reward_this_round
        else:
            performance_score = 0.5

        for aid in self.reputations.keys():
            self.reputations[aid] = np.clip(
                (1 - self.learning_rate) * self.reputations[aid] + \
                self.learning_rate * performance_score, 0, 1)

    def record_actions(self, action_type: str, target_id: str):
        action_key = f"{action_type}_{target_id}"
        self.recent_actions[action_key].append(1) 
        if len(self.recent_actions[action_key]) > self.action_history_window:
            self.recent_actions[action_key].pop(0)

    def calculate_specialization_index(self, all_possible_actions: List[str]) -> Tuple[str, float]:
        total_actions_in_window = sum(sum(counts) for counts in self.recent_actions.values())
        if total_actions_in_window == 0:
            self.specialization_index = 0.0
            self.most_specialized_action = "None"
            return "None", 0.0

        action_sums = {ak: sum(counts) for ak, counts in self.recent_actions.items()}

        proportions = np.array([action_sums.get(ak, 0) / total_actions_in_window for ak in all_possible_action_keys])

        positive_proportions = proportions[proportions > 0]

        if len(positive_proportions) > 1:
            entropy = -np.sum(positive_proportions * np.log2(positive_proportions))
            max_entropy = math.log2(len(positive_proportions)) if len(positive_proportions) > 0 else 0.0
            specialization_index = 1 - (entropy / max_entropy) if max_entropy > 0 else 0.0
        else:
            specialization_index = 1.0 if len(positive_proportions) == 1 else 0.0

        most_specialized_action = max(action_sums, key=action_sums.get) if action_sums else "None"

        self.specialization_index = specialization_index
        self.most_specialized_action = most_specialized_action
        return most_specialized_action, specialization_index

    def consider_strategy_adoption(self, all_agents: Dict[str, 'ConstructionAgent'], current_round: int, total_rounds: int,
                                   adoption_threshold_self_reward_factor: float = 0.5, 
                                   adoption_threshold_other_rep: float = 0.8, 
                                   top_n_percent_mentors: float = 0.25, max_possible_collective_reward_per_round: float = 0):

        expected_total_reward_for_current_round = max_possible_collective_reward_per_round * (current_round + 1)
        dynamic_self_reward_threshold = expected_total_reward_for_current_round * adoption_threshold_self_reward_factor

        if self.total_reward < dynamic_self_reward_threshold: 
            sorted_agents = sorted(all_agents.values(), key=lambda a: a.total_reward, reverse=True)
            num_top_mentors = max(1, int(len(self.all_agent_ids) * top_n_percent_mentors))

            potential_mentors = []
            for mentor_candidate in sorted_agents[:num_top_mentors]: 
                if mentor_candidate.agent_id == self.agent_id: continue

                if self.reputations.get(mentor_candidate.agent_id, 0.0) >= adoption_threshold_other_rep: 
                    potential_mentors.append(mentor_candidate)

            if potential_mentors:
                mentor = max(potential_mentors, key=lambda a: a.total_reward)

                for action_key in set(self.action_strategy.keys()).union(mentor.action_strategy.keys()):
                    if action_key in mentor.action_strategy:
                        self.action_strategy[action_key] = mentor.action_strategy[action_key].copy()
                    elif action_key in self.action_strategy: 
                        pass 
                    else: 
                        self.action_strategy[action_key] = {'success': 1, 'attempts': 2, 'value_est': 0.5}

                if np.random.rand() < self.mutation_rate:
                    for action_key in self.action_strategy.keys():
                        self.action_strategy[action_key]['value_est'] = np.clip(self.action_strategy[action_key]['value_est'] + np.random.uniform(-0.1, 0.1), 0, 1)

                self.epsilon_start = 0.08 

class CooperativeBuildingEnvironment:
    def __init__(self, num_agents: int, total_resource_capacity: int = 50):
        self.num_agents = num_agents
        self.total_resource_capacity = total_resource_capacity
        self.world_resources: Dict[str, Resource] = {}
        self.world_components: Dict[str, Component] = {} 
        self.building_status: Dict[str, BuildingComponent] = {} 
        self.current_building_phase = "house_phase1" # Start with phase 1

        for res_id in RESOURCES.keys():
            self.world_resources[res_id] = Resource(res_id, amount=self.total_resource_capacity // len(RESOURCES))

        for comp_id, blueprint in COMPONENTS.items():
            self.world_components[comp_id] = Component(comp_id, blueprint)

        self._initialize_building_phase(self.current_building_phase)

        self.max_possible_collective_reward_per_round = 100 

        print(f"Environment initialized for {num_agents} agents for building task (Phase: {self.current_building_phase}).")

    def _initialize_building_phase(self, phase_name: str):
        self.building_status = {} # Reset for new phase or augment
        for bc_id, deps in BUILDING_PLAN[phase_name]:
            self.building_status[bc_id] = BuildingComponent(bc_id, deps)
        print(f"  Initialized Building Phase: {phase_name}")

    def _check_phase_complete(self) -> bool:
        return all(bc.assembled for bc in self.building_status.values() if bc.id in BUILDING_PLAN[self.current_building_phase])

    def transition_phase(self):
        if self.current_building_phase == "house_phase1":
            if self._check_phase_complete():
                print("\n--- Phase 1 Complete! Transitioning to Phase 2 ---")
                self.current_building_phase = "house_phase2"
                self._initialize_building_phase(self.current_building_phase)
                return True
        elif self.current_building_phase == "house_phase2":
            if self._check_phase_complete():
                print("\n--- All Building Phases Complete! ---")
                return True
        return False

    def introduce_dynamic_event(self, current_round: int):
        if current_round == 300: # Example event: Wood becomes scarce
            self.world_resources["wood"].amount = 5
            print(f"\n--- Dynamic Event at Round {current_round}: Wood Scarcity! ---")
        elif current_round == 600: # Example event: A wall segment is damaged and needs re-crafting/re-assembling
            if "wall_segment_1" in self.building_status and self.building_status["wall_segment_1"].assembled:
                print(f"\n--- Dynamic Event at Round {current_round}: Wall Segment 1 Damaged! ---")
                # Reset wall_segment_1 to require re-crafting and re-assembly
                wall_segment_base_id = '_'.join("wall_segment_1".split('_')[:-1])
                if wall_segment_base_id in self.world_components:
                    self.world_components[wall_segment_base_id].ready_for_assembly = False
                    self.world_components[wall_segment_base_id].current_craft_time = 0

                self.building_status["wall_segment_1"].crafted_ready = False
                self.building_status["wall_segment_1"].assembled = False
                # Any dependent components will also become unassembled due to unmet dependencies
                for bc_id, bc in self.building_status.items():
                    if "wall_segment_1" in bc.dependencies and bc.assembled:
                        bc.assembled = False
                        print(f"    - {bc_id} (dependent on wall_segment_1) also became unassembled.")

    def get_collective_reward(self) -> float:
        completed_count = sum(1 for bc in self.building_status.values() if bc.assembled)
        total_components_in_current_phase = len(BUILDING_PLAN[self.current_building_phase])
        if total_components_in_current_phase == 0: return 0

        # Reward based on progress in current phase
        reward_per_component = (self.max_possible_collective_reward_per_round / 2) / total_components_in_current_phase
        current_phase_reward = completed_count * reward_per_component

        if self.current_building_phase == "house_phase2" and self._check_phase_complete():
            return self.max_possible_collective_reward_per_round # Full reward for final completion

        return current_phase_reward

    def process_actions(self, agent_actions: Dict[str, Tuple[str, str]], agents_dict: Dict[str, ConstructionAgent]) -> float:
        resource_gains = defaultdict(int)
        craft_progress = defaultdict(int)
        assemble_attempts = defaultdict(lambda: [])

        for agent_id, (action_type, target_id) in agent_actions.items():
            agent = agents_dict[agent_id]
            if action_type == "gather":
                if target_id in self.world_resources and self.world_resources[target_id].amount > 0:
                    agent.current_resources[target_id] += 1
                    self.world_resources[target_id].amount -= 1
            elif action_type == "craft":
                if target_id in self.world_components:
                    can_craft = True
                    for res_id, needed in COMPONENTS[target_id]["resources"].items():
                        if agent.current_resources.get(res_id, 0) < needed:
                            can_craft = False
                            break
                    if can_craft and not self.world_components[target_id].ready_for_assembly:
                        for res_id, needed in COMPONENTS[target_id]["resources"].items():
                            agent.current_resources[res_id] -= needed
                        craft_progress[target_id] += 1 
            elif action_type == "assemble":
                if target_id in self.building_status and not self.building_status[target_id].assembled:
                    assemble_attempts[target_id].append(agent_id) 

        for comp_id, progress in craft_progress.items():
            self.world_components[comp_id].add_craft_time(progress)

        for bc_id, bc in self.building_status.items():
            bc.check_crafted_ready(self.world_components)

        for bc_id, agent_ids in assemble_attempts.items():
            bc = self.building_status[bc_id]
            if bc.crafted_ready and bc.check_dependencies(self.building_status):
                if not bc.assembled: 
                    bc.assemble()

        return self.get_collective_reward()

    def get_all_possible_action_keys(self) -> List[str]:
        actions = []
        for res_id in RESOURCES.keys():
            actions.append(f"gather_{res_id}")
        for comp_id in COMPONENTS.keys():
            actions.append(f"craft_{comp_id}")
        for bc_id in self.building_status.keys(): # Only currently relevant building components
            actions.append(f"assemble_{bc_id}")
        return actions

# --- Simulation Setup ---
NUM_AGENTS = 5
NUM_ROUNDS = 1000 
TOTAL_RESOURCE_CAPACITY = 100 

all_agent_ids = [f"Agent_{i+1}" for i in range(NUM_AGENTS)]

agents_dict = {}

# Assign initial preferred actions
agents_dict['Agent_1'] = ConstructionAgent('Agent_1', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.08, epsilon_end=0.02, mutation_rate=0.05, preferred_action="gather_wood")
agents_dict['Agent_2'] = ConstructionAgent('Agent_2', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.08, epsilon_end=0.02, mutation_rate=0.05, preferred_action="craft_foundation")
agents_dict['Agent_3'] = ConstructionAgent('Agent_3', all_agent_ids, NUM_AGENTS, learning_rate=0.1, epsilon_start=0.1, epsilon_end=0.05, mutation_rate=0.05, preferred_action="gather_stone")
agents_dict['Agent_4'] = ConstructionAgent('Agent_4', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.08, epsilon_end=0.02, mutation_rate=0.15, preferred_action="assemble_roof_panel_1")
agents_dict['Agent_5'] = ConstructionAgent('Agent_5', all_agent_ids, NUM_AGENTS, learning_rate=0.2, epsilon_start=0.08, epsilon_end=0.02, mutation_rate=0.05, preferred_action="craft_wall_segment")

env = CooperativeBuildingEnvironment(NUM_AGENTS, total_resource_capacity=TOTAL_RESOURCE_CAPACITY)
all_possible_action_keys = env.get_all_possible_action_keys() # Initial set of actions

print(f"\n--- Starting {NUM_ROUNDS} Rounds of Complex Cooperative Building Task - Dynamic Role Assignment ---")

for i in range(NUM_ROUNDS):
    env.introduce_dynamic_event(i) # Introduce dynamic events
    if env.transition_phase(): # Check for phase transition
        all_possible_action_keys = env.get_all_possible_action_keys() # Update action list for new phase

    agent_actions_this_round = {}
    for agent_id in all_agent_ids:
        agent_actions_this_round[agent_id] = agents_dict[agent_id].choose_action(all_possible_action_keys, i, NUM_ROUNDS, env.world_components, env.building_status) 

    collective_round_reward = env.process_actions(agent_actions_this_round, agents_dict)

    for agent_id in all_agent_ids:
        agent = agents_dict[agent_id]
        agent.record_actions(agent_actions_this_round[agent_id][0], agent_actions_this_round[agent_id][1])
        agent.calculate_specialization_index(all_possible_action_keys) # Pass updated action keys

        agent.update_learning(
            chosen_action=agent_actions_this_round[agent_id],
            collective_round_reward=collective_round_reward,
            world_components=env.world_components, 
            current_max_possible_collective_reward=env.max_possible_collective_reward_per_round,
            current_round=i
        )
        agents_dict[agent_id].update_reputation_from_round_outcome(collective_round_reward, env.max_possible_collective_reward_per_round)

    if (i + 1) % 100 == 0:
        print(f"\n--- Cultural Transmission Check (Round {i+1}) ---")
        for agent_id in all_agent_ids:
            dynamic_self_reward_threshold_for_adoption = (collective_round_reward / env.max_possible_collective_reward_per_round) * 0.75 if env.max_possible_collective_reward_per_round > 0 else 0

            agents_dict[agent_id].consider_strategy_adoption(all_agents=agents_dict, current_round=i, total_rounds=NUM_ROUNDS,
                                                           adoption_threshold_self_reward_factor=dynamic_self_reward_threshold_for_adoption,
                                                           adoption_threshold_other_rep=0.8,
                                                           top_n_percent_mentors=0.25, max_possible_collective_reward_per_round=env.max_possible_collective_reward_per_round)

        print(f"\nRound {i+1} Summary (Current Phase: {env.current_building_phase}, Collective Reward: {collective_round_reward}, Epsilon_A1: {agents_dict['Agent_1']._get_epsilon(i, NUM_ROUNDS):.2f}, Epsilon_A3: {agents_dict['Agent_3']._get_epsilon(i, NUM_ROUNDS):.2f}):")
        for agent_id in all_agent_ids:
            agent = agents_dict[agent_id]
            print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
            print(f"    Specialization: Most={agent.most_specialized_action}, Index={agent.specialization_index:.2f}")
            for rep_partner_id, rep_score in agent.reputations.items():
                print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")

        print("  Current Building Status:")
        for bc_id, bc in env.building_status.items():
            print(f"    - {bc_id}: Crafted Ready={bc.crafted_ready}, Assembled={bc.assembled}")

print(f"\n--- Simulation Complete ---")
print("\nFinal Agent Rewards:")
for agent_id in all_agent_ids:
    agent = agents_dict[agent_id]
    print(f"  {agent.agent_id}: Total Reward = {agent.total_reward}")
    print(f"    Specialization: Most={agent.most_specialized_action}, Index={agent.specialization_index:.2f}")
    for rep_partner_id, rep_score in agent.reputations.items():
        print(f"    Rep for {rep_partner_id}: {rep_score:.2f}")

final_collective_reward_sum_of_totals = sum(agent.total_reward for agent in agents_dict.values())
print(f"Final Collective Reward (sum of individual totals): {final_collective_reward_sum_of_totals}")

print("\nFinal Building Status:")
for bc_id, bc in env.building_status.items():
    print(f"  - {bc_id}: Crafted Ready={bc.crafted_ready}, Assembled={bc.assembled}")
print(f"Final Building Phase: {env.current_building_phase}")
